INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT128-S3-Q8$batch06$, 128, 3, 8, $batch06$Method$batch06$, $batch06$Politician: It is widely accepted that because democratic politics cannot exist without debate about political issues, and because self-governance flourishes when citizens are allowed to express their feelings verbally, a democratically governed society should refrain from interfering in individual citizens' speech. I argue that a democratically governed society should also refrain from exercising strict control over the clothing and grooming of its citizens, for this is clearly a venue of self-expression, and it can also serve to make a variety of political statements, without using words.$batch06$, $batch06$A logical strategy used in the politician's argument is to$batch06$, $batch06$D$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$argue for a conclusion by suggesting that the opposite conclusion leads to an absurdity$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$reach a general conclusion based on the absence of clear counterexamples to an empirical thesis$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$support a conclusion by claiming that it is widely accepted$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$reach a conclusion based on evidence that is similar to evidence commonly thought to support an analogous case$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$reach a conclusion about what democratically governed societies actually do based on premises about what democratically governed societies should do$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$A democratic society should not strictly control its citizens' clothing and grooming.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$We already accept leaving speech alone because self-expression and political debate matter. Clothing and grooming are also self-expression and can make political statements.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The politician starts with a case people already accept (free speech) and the reasons behind it. Then they show clothing shares those same features: self-expression and political statements. Same reasons, so the same conclusion should follow. That is an analogy.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Reaching a conclusion from evidence similar to the evidence for an accepted, analogous case.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The politician never shows the opposite conclusion is absurd.$batch06$), ($batch06$B$batch06$, $batch06$The argument does not rest on a lack of counterexamples.$batch06$), ($batch06$C$batch06$, $batch06$"Widely accepted" describes the speech case, not the conclusion about clothing. The politician's conclusion is new and argued for, not supported by popularity.$batch06$), ($batch06$D$batch06$, $batch06$The analogous case is speech. The similar evidence is self-expression and political statements, which clothing shares.$batch06$), ($batch06$E$batch06$, $batch06$Every claim is about what societies *should* do. Nothing concludes what they actually do.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT128-S3-Q8$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
